// Overall player stats derived from xp_ledger rows with source = 'event_attendance'.
//
// Two award paths write those rows (see api/events/[id]/checkin and api/hq/xp/operational):
//   - Kiosk/QR check-in:  "Attended <event name>" or "Attended <event name> — N round win(s)"
//   - HQ tile award:      "Attended", "+1 Win", "+1 Win", ... (comma separated labels)
// Both formats are generated by our own code, so they are safe to parse here.

export interface LedgerRow {
  description: string | null;
  created_at: string | null;
}

export interface OverallStats {
  eventsAttended: number;
  matchWins: number;
  weekStreak: number;
}

const DAY_MS = 86_400_000;

function isAttended(description: string): boolean {
  return /^attended/i.test(description.trim());
}

function winsIn(description: string): number {
  const tileWins = description.match(/\+1 Win/g)?.length ?? 0;
  const roundWins = description.match(/(\d+)\s+round win/i);
  return tileWins + (roundWins ? parseInt(roundWins[1], 10) : 0);
}

// Calendar date in Pacific time as a day number, so a Friday-night check-in
// never lands in the wrong week because of UTC.
function pacificDayNumber(date: Date): number {
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone: 'America/Los_Angeles',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).format(date);
  const [y, m, d] = parts.split('-').map(Number);
  return Math.floor(Date.UTC(y, m - 1, d) / DAY_MS);
}

// Monday-start week index. Day 0 (1970-01-01) was a Thursday.
function weekIndex(dayNumber: number): number {
  return Math.floor((dayNumber + 3) / 7);
}

export function computeOverallStats(rows: LedgerRow[], now: Date = new Date()): OverallStats {
  let eventsAttended = 0;
  let matchWins = 0;
  const attendedWeeks = new Set<number>();

  for (const row of rows) {
    const description = row.description ?? '';
    matchWins += winsIn(description);
    if (isAttended(description)) {
      eventsAttended += 1;
      if (row.created_at) {
        attendedWeeks.add(weekIndex(pacificDayNumber(new Date(row.created_at))));
      }
    }
  }

  // The streak stays alive through the current week even if the player
  // hasn't checked in yet this week.
  const current = weekIndex(pacificDayNumber(now));
  let cursor = attendedWeeks.has(current) ? current : current - 1;
  let weekStreak = 0;
  while (attendedWeeks.has(cursor)) {
    weekStreak += 1;
    cursor -= 1;
  }

  return { eventsAttended, matchWins, weekStreak };
}
